SELECT t2.drugname AS drugname FROM (SELECT patient."唯一患者编号" AS uniquepid, treatment."治疗时间" AS treatmenttime, patient."患者院内住院编号" AS patienthealthsystemstayid FROM "治疗" AS treatment JOIN "患者" AS patient ON treatment."患者科室住院编号" = patient."患者科室住院编号" WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '005-66412') AND treatment."治疗名称" = 'vte prophylaxis - compression stockings' AND STRFTIME('%y-%m', treatment."治疗时间") <= '2105-09') AS t1 JOIN (SELECT patient."唯一患者编号" AS uniquepid, medication."药物名称" AS drugname, medication."用药开始时间" AS drugstarttime, patient."患者院内住院编号" AS patienthealthsystemstayid FROM "用药" AS medication JOIN "患者" AS patient ON medication."患者科室住院编号" = patient."患者科室住院编号" WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '005-66412') AND STRFTIME('%y-%m', medication."用药开始时间") <= '2105-09') AS t2 ON t1.uniquepid = t2.uniquepid WHERE t1.treatmenttime < t2.drugstarttime AND t1.patienthealthsystemstayid = t2.patienthealthsystemstayid	eicu
SELECT t2.drugname AS drugname FROM (SELECT patient."唯一患者编号" AS uniquepid, treatment."治疗时间" AS treatmenttime FROM "治疗" AS treatment JOIN "患者" AS patient ON treatment."患者科室住院编号" = patient."患者科室住院编号" WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '007-10135') AND treatment."治疗名称" = 'antipyretics - acetaminophen' AND DATETIME(treatment."治疗时间", 'start of year') = DATETIME(CURRENT_TIME, 'start of year', '-1 year') AND STRFTIME('%m', treatment."治疗时间") = '11') AS t1 JOIN (SELECT patient."唯一患者编号" AS uniquepid, medication."药物名称" AS drugname, medication."用药开始时间" AS drugstarttime FROM "用药" AS medication JOIN "患者" AS patient ON medication."患者科室住院编号" = patient."患者科室住院编号" WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '007-10135') AND DATETIME(medication."用药开始时间", 'start of year') = DATETIME(CURRENT_TIME, 'start of year', '-1 year') AND STRFTIME('%m', medication."用药开始时间") = '11') AS t2 ON t1.uniquepid = t2.uniquepid WHERE t1.treatmenttime < t2.drugstarttime AND DATETIME(t2.drugstarttime) BETWEEN DATETIME(t1.treatmenttime) AND DATETIME(t1.treatmenttime, '+2 day')	eicu
