SELECT treatment."治疗时间" AS treatmenttime FROM "治疗" AS treatment WHERE treatment."患者科室住院编号" IN (SELECT patient."患者科室住院编号" AS patientunitstayid FROM "患者" AS patient WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '011-59493')) AND treatment."治疗名称" = 'valve replacement or repair - emergent' AND DATETIME(treatment."治疗时间") >= DATETIME(CURRENT_TIME, '-4 year') ORDER BY treatment."治疗时间" ASC LIMIT 1	eicu
SELECT medication."用药开始时间" AS drugstarttime FROM "用药" AS medication WHERE medication."患者科室住院编号" IN (SELECT patient."患者科室住院编号" AS patientunitstayid FROM "患者" AS patient WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '005-62766')) AND medication."给药途径" = 'oral' ORDER BY medication."用药开始时间" ASC LIMIT 1	eicu
