SELECT COUNT(*) > 0 AS _col_0 FROM "患者" AS patient WHERE patient."唯一患者编号" = '012-63427' AND patient."入院来源" = 'emergency department' AND DATETIME(patient."科室入院时间") >= DATETIME(CURRENT_TIME, '-3 year')	eicu
