SELECT COUNT(*) > 0 AS _col_0 FROM "治疗" AS treatment WHERE treatment."患者科室住院编号" IN (SELECT patient."患者科室住院编号" AS patientunitstayid FROM "患者" AS patient WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '030-52395')) AND treatment."治疗名称" = 'suprapubic catheter' AND DATETIME(treatment."治疗时间") <= DATETIME(CURRENT_TIME, '-3 year')	eicu
SELECT COUNT(*) AS _col_0 FROM "微生物检验" AS microlab WHERE microlab."患者科室住院编号" IN (SELECT patient."患者科室住院编号" AS patientunitstayid FROM "患者" AS patient WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '025-44495')) AND microlab."培养部位" = 'sputum, expectorated' AND STRFTIME('%y', microlab."采样时间") = '2105'	eicu
SELECT COUNT(*) AS _col_0 FROM "微生物检验" AS microlab WHERE microlab."患者科室住院编号" IN (SELECT patient."患者科室住院编号" AS patientunitstayid FROM "患者" AS patient WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '031-19622')) AND microlab."培养部位" = 'bronchial lavage' AND DATETIME(microlab."采样时间") <= DATETIME(CURRENT_TIME, '-1 year')	eicu
SELECT MAX(lab."检验结果") AS _col_0 FROM "检验" AS lab WHERE lab."患者科室住院编号" IN (SELECT patient."患者科室住院编号" AS patientunitstayid FROM "患者" AS patient WHERE patient."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."唯一患者编号" = '029-8147')) AND lab."检验项目" = 'rbc' AND DATETIME(lab."检验时间") >= DATETIME(CURRENT_TIME, '-173 month') GROUP BY STRFTIME('%y-%m', lab."检验时间")	eicu
SELECT COUNT(DISTINCT patient."唯一患者编号") AS _col_0 FROM "患者" AS patient WHERE patient."出院时间" IS NULL AND patient."年龄" BETWEEN 40 AND 49	eicu
SELECT COUNT(DISTINCT patient."唯一患者编号") AS _col_0 FROM "患者" AS patient WHERE patient."出院时间" IS NULL AND patient."年龄" BETWEEN 30 AND 39	eicu
SELECT SUM(CASE WHEN patient."出院状态" = 'alive' THEN 1 WHEN STRFTIME('%j', patient."出院时间") - STRFTIME('%j', t2.diagnosistime) > 2 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS _col_0 FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosistime AS diagnosistime FROM (SELECT patient."唯一患者编号" AS uniquepid, diagnosis."诊断时间" AS diagnosistime FROM "诊断" AS diagnosis JOIN "患者" AS patient ON diagnosis."患者科室住院编号" = patient."患者科室住院编号" WHERE diagnosis."诊断名称" = 'sepsis - sepsis with single organ dysfunction- metabolic encephalopathy' GROUP BY patient."唯一患者编号" HAVING MIN(diagnosis."诊断时间") = diagnosis."诊断时间") AS t1 WHERE STRFTIME('%j', CURRENT_TIME) - STRFTIME('%j', t1.diagnosistime) > 2 * 365) AS t2 JOIN "患者" AS patient ON t2.uniquepid = patient."唯一患者编号"	eicu
SELECT SUM(CASE WHEN patient."出院状态" = 'alive' THEN 1 WHEN STRFTIME('%j', patient."出院时间") - STRFTIME('%j', t4.diagnosistime) > 3 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS _col_0 FROM (SELECT t2.uniquepid AS uniquepid, t2.diagnosistime AS diagnosistime FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosistime AS diagnosistime FROM (SELECT patient."唯一患者编号" AS uniquepid, diagnosis."诊断时间" AS diagnosistime FROM "诊断" AS diagnosis JOIN "患者" AS patient ON diagnosis."患者科室住院编号" = patient."患者科室住院编号" WHERE diagnosis."诊断名称" = 'valvular stenosis' GROUP BY patient."唯一患者编号" HAVING MIN(diagnosis."诊断时间") = diagnosis."诊断时间") AS t1) AS t2 JOIN (SELECT patient."唯一患者编号" AS uniquepid, medication."用药开始时间" AS drugstarttime FROM "用药" AS medication JOIN "患者" AS patient ON medication."患者科室住院编号" = patient."患者科室住院编号" WHERE medication."药物名称" = 'potassium chloride crys er 20 meq po tbcr') AS t3 ON t2.uniquepid = t3.uniquepid WHERE t2.diagnosistime < t3.drugstarttime) AS t4 JOIN "患者" AS patient ON t4.uniquepid = patient."唯一患者编号"	eicu
SELECT SUM(CASE WHEN patient."出院状态" = 'alive' THEN 1 WHEN STRFTIME('%j', patient."出院时间") - STRFTIME('%j', t4.diagnosistime) > 2 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS _col_0 FROM (SELECT t2.uniquepid AS uniquepid, t2.diagnosistime AS diagnosistime FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosistime AS diagnosistime FROM (SELECT patient."唯一患者编号" AS uniquepid, diagnosis."诊断时间" AS diagnosistime FROM "诊断" AS diagnosis JOIN "患者" AS patient ON diagnosis."患者科室住院编号" = patient."患者科室住院编号" WHERE diagnosis."诊断名称" = 'malignancy' GROUP BY patient."唯一患者编号" HAVING MIN(diagnosis."诊断时间") = diagnosis."诊断时间") AS t1) AS t2 JOIN (SELECT patient."唯一患者编号" AS uniquepid, medication."用药开始时间" AS drugstarttime FROM "用药" AS medication JOIN "患者" AS patient ON medication."患者科室住院编号" = patient."患者科室住院编号" WHERE medication."药物名称" = 'piperacillin-tazobactam 3.375 g ivpb') AS t3 ON t2.uniquepid = t3.uniquepid WHERE t2.diagnosistime < t3.drugstarttime) AS t4 JOIN "患者" AS patient ON t4.uniquepid = patient."唯一患者编号"	eicu
SELECT t4.diagnosisname AS diagnosisname FROM (SELECT t3.diagnosisname AS diagnosisname, DENSE_RANK() OVER (ORDER BY t3.c1 DESC) AS c2 FROM (SELECT t2.diagnosisname AS diagnosisname, 100 - SUM(CASE WHEN patient."出院状态" = 'alive' THEN 1 WHEN STRFTIME('%j', patient."出院时间") - STRFTIME('%j', t2.diagnosistime) > 3 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS c1 FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosisname AS diagnosisname, t1.diagnosistime AS diagnosistime FROM (SELECT patient."唯一患者编号" AS uniquepid, diagnosis."诊断名称" AS diagnosisname, diagnosis."诊断时间" AS diagnosistime FROM "诊断" AS diagnosis JOIN "患者" AS patient ON diagnosis."患者科室住院编号" = patient."患者科室住院编号" GROUP BY patient."唯一患者编号", diagnosis."诊断名称" HAVING MIN(diagnosis."诊断时间") = diagnosis."诊断时间") AS t1 WHERE STRFTIME('%j', CURRENT_TIME) - STRFTIME('%j', t1.diagnosistime) > 3 * 365) AS t2 JOIN "患者" AS patient ON t2.uniquepid = patient."唯一患者编号" GROUP BY t2.diagnosisname) AS t3) AS t4 WHERE t4.c2 <= 5	eicu
SELECT MIN(t1.c1) AS _col_0 FROM (SELECT SUM(cost."费用") AS c1 FROM "费用" AS cost WHERE cost."患者院内住院编号" IN (SELECT patient."患者院内住院编号" AS patienthealthsystemstayid FROM "患者" AS patient WHERE patient."患者科室住院编号" IN (SELECT treatment."患者科室住院编号" AS patientunitstayid FROM "治疗" AS treatment WHERE treatment."治疗名称" = 'nitroglycerin - transdermal')) AND DATETIME(cost."计费时间", 'start of year') = DATETIME(CURRENT_TIME, 'start of year', '-0 year') GROUP BY cost."患者院内住院编号") AS t1	eicu
SELECT COUNT(DISTINCT t2.uniquepid) AS _col_0 FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosistime AS diagnosistime, t1.patienthealthsystemstayid AS patienthealthsystemstayid FROM (SELECT patient."唯一患者编号" AS uniquepid, diagnosis."诊断时间" AS diagnosistime, patient."患者院内住院编号" AS patienthealthsystemstayid FROM "诊断" AS diagnosis JOIN "患者" AS patient ON diagnosis."患者科室住院编号" = patient."患者科室住院编号" WHERE diagnosis."诊断名称" = 'seizures') AS t1 GROUP BY t1.uniquepid HAVING MIN(t1.diagnosistime) = t1.diagnosistime AND STRFTIME('%y', t1.diagnosistime) = '2102') AS t2 JOIN (SELECT patient."唯一患者编号" AS uniquepid, patient."患者院内住院编号" AS patienthealthsystemstayid, patient."出院时间" AS hospitaldischargetime FROM "患者" AS patient WHERE patient."出院状态" = 'expired') AS t3 ON t2.uniquepid = t3.uniquepid WHERE t2.patienthealthsystemstayid = t3.patienthealthsystemstayid	eicu
